#include "twin/DigitalTwin.hpp"
#include "platform/AircraftPlatformCatalog.hpp"
#include <algorithm>
namespace nexvary::avionics { namespace {int rank(TwinState s)noexcept{switch(s){case TwinState::Unknown:return 0;case TwinState::Nominal:return 1;case TwinState::Degraded:return 2;case TwinState::Fault:return 3;}return 0;}void escalate(TwinSubsystem& s,TwinState c){if(rank(c)>rank(s.state))s.state=c;}std::string groupFor(const AircraftPlatformProfile& p,std::string_view source){for(const auto& n:p.twinTopology){if(source==n.id)return n.id;for(const auto& c:n.channels)if(source==c)return n.id;}return{};}}
DigitalTwinSnapshot DigitalTwinModel::build(const std::map<std::string,SensorSample>& s,const std::vector<HealthIssue>& i){return build("generic-jet",s,i);} DigitalTwinSnapshot DigitalTwinModel::build(std::string_view platformId,const std::map<std::string,SensorSample>& sensors,const std::vector<HealthIssue>& issues){DigitalTwinSnapshot r;const auto p=AircraftPlatformCatalog::find(platformId);if(!p)return r;for(const auto& n:p->twinTopology){TwinSubsystem sub;sub.id=n.id;sub.expectedChannels=n.channels.size();for(const auto& name:n.channels){const auto it=sensors.find(name);if(it==sensors.end())continue;++sub.observedChannels;if(it->second.valid)++sub.validChannels;else escalate(sub,TwinState::Fault);}if(sub.observedChannels==0)sub.state=TwinState::Unknown;else if(sub.state!=TwinState::Fault)sub.state=sub.observedChannels<sub.expectedChannels?TwinState::Degraded:TwinState::Nominal;for(const auto& issue:issues){if(groupFor(*p,issue.subsystem)!=n.id)continue;++sub.issueCount;if(issue.severity==Severity::Fault)escalate(sub,TwinState::Fault);else if(issue.severity==Severity::Warning)escalate(sub,TwinState::Degraded);}const double comp=sub.expectedChannels?100.0*static_cast<double>(sub.validChannels)/static_cast<double>(sub.expectedChannels):0.0;switch(sub.state){case TwinState::Nominal:sub.healthPercent=comp;++r.nominalCount;break;case TwinState::Degraded:sub.healthPercent=std::min(comp,75.0);++r.degradedCount;break;case TwinState::Fault:sub.healthPercent=std::min(comp,25.0);++r.faultCount;break;case TwinState::Unknown:sub.healthPercent=0;++r.unknownCount;break;}r.subsystems.push_back(std::move(sub));}return r;}
const char* to_string(TwinState s)noexcept{switch(s){case TwinState::Unknown:return"UNKNOWN";case TwinState::Nominal:return"NOMINAL";case TwinState::Degraded:return"DEGRADED";case TwinState::Fault:return"FAULT";}return"UNKNOWN";}
} // namespace nexvary::avionics
